38	// =============================================================================
39	// Helpers
40	// =============================================================================
41	
42	function wrapSvg(content: string, w: number, h: number): string {
43	  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}">
44	  <style>
45	    .title { font-family: system-ui, -apple-system, sans-serif; font-size: 18px; font-weight: bold; fill: #111827; }
46	    .label { font-family: system-ui, -apple-system, sans-serif; font-size: 13px; fill: #374151; }
47	    .value { font-family: system-ui, -apple-system, sans-serif; font-size: 13px; fill: #6B7280; }
48	    .note { font-family: system-ui, -apple-system, sans-serif; font-size: 11px; fill: #9CA3AF; }
49	    .grid { stroke: #E5E7EB; stroke-width: 1; stroke-dasharray: 4 4; }
50	    .axis { stroke: #D1D5DB; stroke-width: 2; }
51	  </style>
52	${content}
53	</svg>`;
54	}
55	
56	function truncate(s: string, maxLen: number): string {
57	  if (s.length <= maxLen) return s;
58	  return s.slice(0, maxLen - 1) + '…';
59	}
60	
61	/**
62	 * Compute a polar-to-cartesian point.
63	 */
64	function polarPoint(cx: number, cy: number, r: number, angleDeg: number): { x: number; y: number } {
65	  const rad = (angleDeg * Math.PI) / 180;
66	  return { x: cx + r * Math.cos(rad), y: cy + r * Math.sin(rad) };
67	}
68	
69	/**
70	 * Build an SVG arc path for a donut segment (inner to outer).
71	 * Angles in degrees, measured clockwise from the positive x-axis.
72	 */
73	function donutArcPath(
74	  cx: number, cy: number,
75	  innerR: number, outerR: number,
76	  startDeg: number, endDeg: number,
77	): string {
78	  // Clamp angles
79	  let start = startDeg;
80	  let end = endDeg;
81	  // Normalize to 0-360
82	  const sweep = end - start;
83	
84	  const outerStart = polarPoint(cx, cy, outerR, start);
85	  const outerEnd = polarPoint(cx, cy, outerR, end);
86	  const innerStart = polarPoint(cx, cy, innerR, start);
87	  const innerEnd = polarPoint(cx, cy, innerR, end);
88	
89	  const largeArc = sweep > 180 ? 1 : 0;
90	
91	  return [
92	    `M ${outerStart.x.toFixed(2)} ${outerStart.y.toFixed(2)}`,
93	    `A ${outerR} ${outerR} 0 ${largeArc} 1 ${outerEnd.x.toFixed(2)} ${outerEnd.y.toFixed(2)}`,
94	    `L ${innerEnd.x.toFixed(2)} ${innerEnd.y.toFixed(2)}`,
95	    `A ${innerR} ${innerR} 0 ${largeArc} 0 ${innerStart.x.toFixed(2)} ${innerStart.y.toFixed(2)}`,
96	    'Z',
97	  ].join(' ');
98	}
