237	
238	    const colors = this.colorScheme === 'colorblind'
239	      ? SENTIMENT_COLORS_COLORBLIND
240	      : SENTIMENT_COLORS_DEFAULT;
241	
242	    // Sort entries for consistent rendering: positive, neutral, negative
243	    const sorted: [string, number][] = ['positive', 'neutral', 'negative']
244	      .map((k) => [k, sentimentDistribution[k] ?? 0]);
245	
246	    const paths: string[] = [];
247	    const legendItems: string[] = [];
248	
249	    // Start from the top (-90 degrees)
250	    let currentAngle = -90;
251	
252	    sorted.forEach(([key, value], idx) => {
253	      const color = colors[key] || '#6B7280';
254	
255	      // Skip 0-value sectors — don't generate path, don't update currentAngle
256	      if (value > 0) {
257	        const pct = value / total;
258	        const sweepDeg = pct * 360;
259	        const endAngle = currentAngle + sweepDeg;
260	
261	        // Add pattern defs for colorblind
262	        if (this.colorScheme === 'colorblind') {
263	          // Use texture via pattern
264	          paths.push(donutArcPath(cx, cy, innerR, outerR, currentAngle, endAngle));
265	          paths.push(`  <path d="${donutArcPath(cx, cy, innerR - 2, outerR + 2, currentAngle, endAngle)}" fill="none" stroke="#333" stroke-width="1" />`);
