268	        }
269	
270	        currentAngle = endAngle;
271	      }
272	
273	      // Always show legend (including 0-value categories)
274	      const legendY = 150 + idx * 30;
275	      legendItems.push(`  <rect x="430" y="${legendY}" width="12" height="12" rx="2" fill="${color}" />`);
276	      legendItems.push(`  <text class="label" x="450" y="${legendY + 10}">${SENTIMENT_LABELS[key] || key} (${value})</text>`);
277	    });
