283	      `  <text class="note" x="${cx}" y="${cy + 12}" text-anchor="middle" font-size="12">条</text>`,
284	      legendItems.join('\n'),
285	      `  <text class="note" x="${w / 2}" y="${h - 20}" text-anchor="middle">数据来源: Daily AI Insight Engine — ${date}</text>`,
286	    ].join('\n');
287	
288	    return wrapSvg(svgContent, w, h);
