295	  generateTrendRadar(trends: TrendAnalysis, date: string): string {
296	    log.info(`Generating trend radar for ${date}`);
297	
298	    const w = 600;
299	    const h = 600;
300	    const cx = 300;
301	    const cy = 300;
302	    const axisLen = 200;
303	
304	    type TrendDimensionKey = 'technology' | 'application' | 'policy' | 'capital';
305	
306	    interface AxisDef {
307	      key: TrendDimensionKey;
308	      label: string;
309	      angleDeg: number; // clockwise from positive x-axis
310	    }
311	
312	    const axes: AxisDef[] = [
313	      { key: 'technology', label: '技术', angleDeg: -90 },
314	      { key: 'application', label: '应用', angleDeg: 0 },
315	      { key: 'policy', label: '政策', angleDeg: 90 },
316	      { key: 'capital', label: '资本', angleDeg: 180 },
317	    ];
318	
319	    // Helper to get data point on an axis
320	    const getPoint = (angleDeg: number, ratio: number) =>
321	      polarPoint(cx, cy, axisLen * ratio, angleDeg);
322	
323	    // Grid polygons (0.25, 0.5, 0.75, 1.0)
324	    const gridPolygons: string[] = [];
325	    for (const ratio of [0.25, 0.5, 0.75, 1.0]) {
326	      const pts = axes.map((a) => {
327	        const p = getPoint(a.angleDeg, ratio);
328	        return `${p.x.toFixed(1)},${p.y.toFixed(1)}`;
329	      });
330	      gridPolygons.push(`  <polygon class="grid" points="${pts.join(' ')}" fill="none" />`);
331	    }
332	
333	    // Axes lines from center to edge
334	    const axisLines: string[] = [];
335	    const axisLabels: string[] = [];
336	    axes.forEach((a) => {
337	      const tip = getPoint(a.angleDeg, 1.0);
338	      axisLines.push(`  <line class="axis" x1="${cx}" y1="${cy}" x2="${tip.x.toFixed(1)}" y2="${tip.y.toFixed(1)}" />`);
339	
340	      // Label at tip + offset
341	      const offset = 20;
342	      let lx = tip.x;
343	      let ly = tip.y;
344	      let anchor = 'middle';
345	      if (a.angleDeg === -90) { ly = tip.y - offset; anchor = 'middle'; }
346	      else if (a.angleDeg === 0) { lx = tip.x + offset; anchor = 'start'; }
347	      else if (a.angleDeg === 90) { ly = tip.y + offset; anchor = 'middle'; }
348	      else if (a.angleDeg === 180) { lx = tip.x - offset; anchor = 'end'; }
349	
350	      axisLabels.push(`  <text class="label" x="${lx.toFixed(1)}" y="${ly.toFixed(1)}" text-anchor="${anchor}" font-weight="bold" font-size="14">${a.label}</text>`);
351	
352	    });
353	
354	    // Data polygon
355	    const dataPoints = axes.map((a) => {
356	      const dim = trends[a.key];
357	      const conf = dim?.confidence ?? 0;
358	      const p = getPoint(a.angleDeg, conf);
359	      return `${p.x.toFixed(1)},${p.y.toFixed(1)}`;
360	    });
361	
362	    // Data value labels at each axis
363	    const dataLabels: string[] = [];
364	    axes.forEach((a) => {
365	      const dim = trends[a.key];
366	      const conf = dim?.confidence ?? 0;
367	      const p = getPoint(a.angleDeg, conf);
368	      const off = 12;
369	      const dx = a.angleDeg === 180 ? -off : a.angleDeg === 0 ? off : 0;
370	      const dy = a.angleDeg === -90 ? -off : a.angleDeg === 90 ? off : 0;
371	      const anchor = a.angleDeg === 180 ? 'end' : a.angleDeg === 0 ? 'start' : 'middle';
372	      dataLabels.push(`  <text class="value" x="${(p.x + dx).toFixed(1)}" y="${(p.y + dy).toFixed(1)}" text-anchor="${anchor}" font-size="13" font-weight="bold" fill="#3B82F6">${conf.toFixed(2)}</text>`);
373	    });
374	
375	    const svgContent = [
376	      `  <text class="title" x="${w / 2}" y="40" text-anchor="middle">四维趋势雷达 — ${date}</text>`,
377	      gridPolygons.join('\n'),
378	      axisLines.join('\n'),
379	      axisLabels.join('\n'),
380	      `  <polygon points="${dataPoints.join(' ')}" fill="rgba(59, 130, 246, 0.2)" stroke="#3B82F6" stroke-width="2" />`,
381	      dataLabels.join('\n'),
382	      `  <text class="note" x="${w / 2}" y="${h - 20}" text-anchor="middle">数据来源: Daily AI Insight Engine — ${date}</text>`,
383	    ].join('\n');
384	
385	    return wrapSvg(svgContent, w, h);
386	  }
