5	// =============================================================================
6	// MermaidGenerator
7	// =============================================================================
8	
9	export class MermaidGenerator {
10	  // ---------------------------------------------------------------------------
11	  // Timeline
12	  // ---------------------------------------------------------------------------
13	
14	  generateTimeline(
15	    events: Array<{ title: string; score: number; published_at: string }>,
16	    date: string,
17	  ): string {
18	    log.info(`Generating Mermaid timeline for ${date} (${events.length} events)`);
19	
20	    // Sort events by published_at ascending
21	    const sorted = [...events].sort(
22	      (a, b) => new Date(a.published_at).getTime() - new Date(b.published_at).getTime(),
23	    );
24	
25	    const lines: string[] = [];
26	    lines.push('timeline');
27	    lines.push(`    title 今日 AI 显著事件时间线 — ${date}`);
28	
29	    for (const evt of sorted) {
30	      const time = this.extractTime(evt.published_at);
31	      const marker = this.scoreMarker(evt.score);
32	      lines.push(`    ${time} : ${marker} ${evt.title} (${evt.score}/10)`);
33	    }
34	
35	    return lines.join('\n');
36	  }
37	
38	  // ---------------------------------------------------------------------------
39	  // Entity graph
40	  // ---------------------------------------------------------------------------
41	
42	  generateEntityGraph(
43	    coOccurrence: Array<{ source: string; target: string; weight: number }>,
44	    _date: string,
45	  ): string {
46	    log.info(`Generating Mermaid entity graph (${coOccurrence.length} edges)`);
47	
48	    const lines: string[] = [];
49	    lines.push('graph LR');
50	
51	    // Collect unique nodes and assign IDs
52	    const nodeIds = new Map<string, string>();
53	    let nextId = 0;
54	
55	    const getId = (name: string): string => {
56	      if (!nodeIds.has(name)) {
57	        const id = String.fromCharCode(65 + nextId); // A, B, C, ...
58	        nextId++;
59	        nodeIds.set(name, id);
60	      }
61	      return nodeIds.get(name)!;
62	    };
63	
64	    // First pass: declare all nodes
65	    const allNames = new Set<string>();
66	    for (const edge of coOccurrence) {
67	      allNames.add(edge.source);
68	      allNames.add(edge.target);
69	    }
70	    for (const name of allNames) {
71	      const id = getId(name);
72	      lines.push(`    ${id}[${name}]`);
73	    }
74	
75	    // Second pass: edges
76	    for (const edge of coOccurrence) {
77	      const srcId = getId(edge.source);
78	      const tgtId = getId(edge.target);
79	      const arrow = edge.weight >= 3 ? '==>' : '-->';
80	      lines.push(`    ${srcId} ${arrow}|${edge.weight}次| ${tgtId}`);
81	    }
82	
83	    return lines.join('\n');
84	  }
85	
86	  // ---------------------------------------------------------------------------
87	  // Helpers
88	  // ---------------------------------------------------------------------------
89	
90	  /**
91	   * Extract HH:MM from an ISO 8601 timestamp.
92	   */
93	  private extractTime(isoString: string): string {
94	    try {
95	      const d = new Date(isoString);
96	      const hh = String(d.getUTCHours()).padStart(2, '0');
97	      const mm = String(d.getUTCMinutes()).padStart(2, '0');
98	      return `${hh}:${mm}`;
99	    } catch {
100	      return '--:--';
101	    }
102	  }
103	
104	  /**
105	   * Return a marker emoji based on score:
106	   *   >= 7  → 🔴
107	   *   4-6   → 🟡
108	   *   1-3   → 🟢
109	   */
110	  private scoreMarker(score: number): string {
111	    if (score >= 7) return '🔴';
112	    if (score >= 4) return '🟡';
113	    return '🟢';
114	  }
115	}
